    if value is None:
        return "NULL"
    if value is True:
        return "TRUE"
    if value is False:
        return "FALSE"
    return str(value)


def format_result(result: QueryResult) -> str:
    """Render a QueryResult as text (no trailing newline)."""
    if not result.columns:
        return f"OK ({result.row_count} rows affected)"
    cells = [[format_value(v) for v in row] for row in result.rows]
    widths = [len(c) for c in result.columns]
    for row in cells:
        for i, text in enumerate(row):
            if i < len(widths):
                widths[i] = max(widths[i], len(text))

    def fmt(items: list[str]) -> str:
        return " | ".join(t.ljust(widths[i]) for i, t in enumerate(items))

    lines = [fmt(list(result.columns)), " | ".join("-" * w for w in widths)]
    lines.extend(fmt(row) for row in cells)
    n = len(result.rows)
    lines.append("(1 row)" if n == 1 else f"({n} rows)")
    return "\\n".join(lines)


def run_repl(
    stdin: TextIO,
    stdout: TextIO,
    stderr: TextIO,
    engine: Optional[Engine] = None,
) -> int:
    """Read SQL from ``stdin`` line by line and execute it."""
    if engine is None:
        engine = Engine()

    def run(sql: str) -> None:
        try:
            result = engine.execute(sql)
        except MiniDBError as exc:
            stderr.write(f"ERROR: {exc}\\n")
            return
        stdout.write(format_result(result) + "\\n")

    buffer = ""
    for line in stdin:
        if line.strip() == ".exit":
            break
        buffer += line
        if buffer.strip().endswith(";"):
            run(buffer)
            buffer = ""
    else:
        if buffer.strip():
            run(buffer)
    return 0


def main(argv: Optional[list[str]] = None) -> int:
    """CLI entry point: run the REPL on sys.stdin/stdout/stderr."""
    return run_repl(sys.stdin, sys.stdout, sys.stderr)


